<section class="panel upload-panel"><div><span class="eyebrow">MEDIA LIBRARY</span><h2>بارگذاری تصویر</h2><p class="muted">JPG، PNG، WebP، GIF و AVIF · حداکثر ۸ مگابایت</p></div><form method="post" enctype="multipart/form-data" class="upload-form"><?= csrf_field() ?><input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" required><button class="button primary" type="submit">بارگذاری</button></form></section><div class="media-grid"><?php foreach($items as $i): ?><article class="media-card"><img src="<?= e(url('media/'.$i['id'])) ?>" alt="<?= e($i['alt_text']) ?>" loading="lazy"><div class="media-card-info"><strong title="<?= e($i['original_name']) ?>"><?= e($i['original_name']) ?></strong><small><?= number_format((int)$i['file_size']/1024,1) ?> KB · <?= (int)$i['width'] ?>×<?= (int)$i['height'] ?></small><div class="media-card-actions"><button type="button" class="text-action" data-copy="<?= e(url('media/'.$i['id'])) ?>">کپی لینک</button><form method="post" data-confirm="این تصویر حذف شود؟"><?= csrf_field() ?><input type="hidden" name="delete_id" value="<?= (int)$i['id'] ?>"><button class="link-danger">حذف</button></form></div></div></article><?php endforeach; ?></div><?php if(!$items): ?><div class="panel empty-state">کتابخانه رسانه خالی است.</div><?php endif; ?>
